import { useEffect, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { getActiveNotebook } from '@/db/repo.js';
import { t } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { Upgrade } from './Upgrade.js';
import { cheapestPrice, offerable, price, useBilling } from './state.js';
import styles from './ProOffer.module.css';

/**
 * Where an offer is being made, which decides only its words. Every moment
 * the app mentions Pro is one of these, so the copy for all of them lives in
 * one catalogue rather than being written again at each call site.
 *
 * - `resting`: the AI allowance has run out for today. The one moment
 *   somebody has just been stopped by the thing Pro lifts.
 * - `aiIdle`: the AI screen, before anything has been asked for.
 * - `settings`: the plan row, where somebody went looking.
 * - `readText`: somebody on the free plan has just asked Lexpad to read a
 *   text for them, which is the moment they wanted the thing Pro is.
 * - `voice`: the microphone in the add sheet, tapped by somebody whose plan
 *   does not include it.
 * - `lex`: the assistant, which is Pro in its entirety rather than a
 *   quantity of something. There is no free amount of it to have run out
 *   of, so this is the only occasion that stands in place of a screen.
 */
export type Occasion = 'resting' | 'aiIdle' | 'settings' | 'readText' | 'voice' | 'lex';

interface ProOfferProps {
  occasion: Occasion;
  /** Quieter, for a place that is not about money. */
  subtle?: boolean;
  /**
   * The notebook this offer is about, when it is not the one the app is
   * showing. The add sheet routes a word by its script, so the notebook it
   * is about to write to is the one whose price applies.
   */
  about?: { targetLang: string; meaningLang: string } | undefined;
}

/**
 * An offer of Pro, or nothing at all.
 *
 * It renders nothing unless all of these hold, and each is a deliberate
 * silence rather than an oversight:
 *
 * - the account is not already paying, so nobody is sold what they have;
 * - the server says this client may sell, which is what keeps a build under
 *   review from showing a price it cannot honour;
 * - there is a price to show, because a number we are unsure of is worse
 *   than no offer;
 * - the notebook is not one Lexpad never charges for. Persian learners are
 *   not a market, and showing them a reason to pay would be a small lie
 *   told to the people this was built for.
 *
 * It asks the server for the plan once, the first time an offer might be
 * shown, and never stores the answer.
 */
export function ProOffer({ occasion, subtle = false, about }: ProOfferProps): React.JSX.Element | null {
  const state = useBilling((s) => s.state);
  const ensure = useBilling((s) => s.ensure);
  const [open, setOpen] = useState(false);
  const active = useLiveQuery(getActiveNotebook, undefined, []);
  const notebook = about ?? active;

  useEffect(() => {
    ensure();
  }, [ensure]);

  const cheapest = cheapestPrice(state);

  if (!offerable(state, notebook?.targetLang, notebook?.meaningLang) || cheapest === undefined) {
    return null;
  }

  return (
    <>
      <div className={subtle ? styles.cardSubtle : styles.card}>
        <div className={styles.text}>
          <p className={styles.title}>{t(`pro.${occasion}.title`)}</p>
          <p className={styles.line}>{t(`pro.${occasion}.line`)}</p>
        </div>
        <button
          type="button"
          className={styles.action}
          onClick={() => {
            setOpen(true);
          }}
        >
          <span>{t('pro.see')}</span>
          <span className={styles.from}>
            {t('pro.from', { amount: price(cheapest.amountMinor, cheapest.currency) })}
          </span>
          <Icon name="chevronRight" size={15} weight={2} />
        </button>
      </div>
      {open && (
        <Upgrade
          onClose={() => {
            setOpen(false);
          }}
        />
      )}
    </>
  );
}
